{"code": "module alu(
    input  [31:0] a,
    input  [31:0] b,
    input  [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);
    wire [32:0] res;
    assign zero = (r == 32'b0);
    assign carry = (aluc == ADD || aluc == ADDU || aluc == SUB || aluc == SUBU) ? res[32] : 1'b0;
    assign overflow = (aluc == ADD) ? ((~a[31] & ~b[31] & r[31]) | (a[31] & b[31] & ~r[31])) :
