    assign r = res[31:0];
    assign negative = r[31];
    assign flag = (aluc == SLT) ? ($signed(a) < $signed(b)) :
                  (aluc == SLTU) ? (a < b) : 1'b0;

    always @(*) begin
        case (aluc)
            ADD:   res = {1'b0, a} + {1'b0, b};
            ADDU:  res = {1'b0, a} + {1'b0, b};
            SUB:   res = {1'b0, a} - {1'b0, b};
            SUBU:  res = {1'b0, a} - {1'b0, b};
            AND:   res = a & b;
            OR:    res = a | b;
            XOR:   res = a ^ b;
