            SRL:   res = b >> a[4:0];
            SRA:   res = $signed(b) >>> a[4:0];
            SLLV:  res = b << a[4:0];
            SRLV:  res = b >> a[4:0];
            SRAV:  res = $signed(b) >>> a[4:0];
